Creating an optimized JavaScript (JSX) script for Adobe InDesign to convert a document from spreads to single pages while retaining the original layout characteristics and master page references requires attention to detail in handling page geometry, master page application, and object placement.

Below is a sample JSX script for this task. Before running the script, make sure to backup your document, as scripts can alter your document irreversibly.

```javascript
// Open the document you want to process
var doc = app.activeDocument;

if (!doc) {
    alert("Please open a document before running this script.");
} else {
    // Begin transaction for undo support
    app.scriptPreferences.enableRedraw = false;
    app.doScript(main, ScriptLanguage.JAVASCRIPT, undefined, UndoModes.ENTIRE_SCRIPT, "Convert Spreads to Single Pages");

    app.scriptPreferences.enableRedraw = true;
}

function main() {
    for (var i = doc.spreads.length - 1; i >= 0; i--) {
        var spread = doc.spreads[i];

        if (spread.pages.length > 1) {
            processSpread(spread);
        }
    }
}

function processSpread(spread) {
    var layoutStartsOn = spread.pages[0].side;

    var singlePages = [];

    // Collecting all pages from spread
    for (var j = spread.pages.length - 1; j >= 0; j--) {
        var page = spread.pages[j];
        var newPage = doc.pages.add(LocationOptions.AFTER, page);

        newPage.marginPreferences = page.marginPreferences;
        newPage.appliedMaster = page.appliedMaster;

        // Move all elements in place
        var pageItems = page.allPageItems;
        for (var k = pageItems.length - 1; k >= 0; k--) {
            var item = pageItems[k];
            item.duplicate(newPage, [0, 0]);
        }

        singlePages.push(page);
    }

    // Remove the original spread
    for (var m = singlePages.length - 1; m >= 0; m--) {
        singlePages[m].remove();
    }
}
```

### Key Points:
- **Backup** your document. This script alters your document structure.
- The script includes transactions for undo support, allowing you to revert the document to its initial state before the script ran.
- It processes each spread, collects pages and duplicate items to a new page created for each spread page.
- Each newly created page retains margin preferences and references to applied master pages.
- The original pages from the spread are removed after their content is duplicated.

This script assumes the document is fairly simple, and additional error checking or handling might be necessary for more complex documents with conditional text, anchored objects, or interactive elements. Adjust the script to handle these cases if necessary.

